#!/usr/bin/env python3
import sys, os, shlex, time, struct, zlib, zipfile, io, stat
from dataclasses import dataclass
from typing import Optional, List, Tuple

VERSION = "2.8"
ZLIB_VERSION_TEXT = "1.2.11"

HELP_TEXT = """Usage: pigz [options] [files ...]
  will compress files in place, adding the suffix '.gz'. If no files are
  specified, stdin will be compressed to stdout. pigz does what gzip does,
  but spreads the work over multiple processors and cores when compressing.

Options:
  -0 to -9, -11        Compression level (level 11, zopfli, is much slower)
  --fast, --best       Compression levels 1 and 9 respectively
  -A, --alias xxx      Use xxx as the name for any --zip entry from stdin
  -b, --blocksize mmm  Set compression block size to mmmK (default 128K)
  -c, --stdout         Write all processed output to stdout (won't delete)
  -C, --comment ccc    Put comment ccc in the gzip or zip header
  -d, --decompress     Decompress the compressed input
  -f, --force          Force overwrite, compress .gz, links, and to terminal
  -F  --first          Do iterations first, before block split for -11
  -h, --help           Display a help screen and quit
  -H, --huffman        Use only Huffman coding for compression
  -i, --independent    Compress blocks independently for damage recovery
  -I, --iterations n   Number of iterations for -11 optimization
  -J, --maxsplits n    Maximum number of split blocks for -11
  -k, --keep           Do not delete original file after processing
  -K, --zip            Compress to PKWare zip (.zip) single entry format
  -l, --list           List the contents of the compressed input
  -L, --license        Display the pigz license and quit
  -m, --no-time        Do not store or restore mod time
  -M, --time           Store or restore mod time
  -n, --no-name        Do not store or restore file name or mod time
  -N, --name           Store or restore file name and mod time
  -O  --oneblock       Do not split into smaller blocks for -11
  -p, --processes n    Allow up to n compression threads (default is the
                       number of online processors, or 8 if unknown)
  -q, --quiet          Print no messages, even on error
  -r, --recursive      Process the contents of all subdirectories
  -R, --rsyncable      Input-determined block locations for rsync
  -S, --suffix .sss    Use suffix .sss instead of .gz (for compression)
  -t, --test           Test the integrity of the compressed input
  -U, --rle            Use run-length encoding for compression
  -v, --verbose        Provide more verbose output
  -V  --version        Show the version of pigz
  -Y  --synchronous    Force output file write to permanent storage
  -z, --zlib           Compress to zlib (.zz) instead of gzip format
  --                   All arguments after "--" are treated as files
"""

LICENSE_TEXT = """pigz 2.8
Copyright (C) 2007-2023 Mark Adler
Subject to the terms of the zlib license.
No warranty is provided or implied.
"""

@dataclass
class Options:
    level: int = 6
    block_k: int = 128
    processes: int = 0
    stdout: bool = False
    decompress: bool = False
    test: bool = False
    list_mode: bool = False
    force: bool = False
    keep: bool = False
    zip_mode: bool = False
    zlib_mode: bool = False
    recursive: bool = False
    independent: bool = False
    rsyncable: bool = False
    quiet: bool = False
    verbose: int = 0
    store_name: bool = True
    store_time: bool = True
    suffix: str = ".gz"
    comment: Optional[str] = None
    alias: str = "-"
    strategy: int = zlib.Z_DEFAULT_STRATEGY
    sync: bool = False

@dataclass
class ParsedName:
    name: Optional[str]  # None means stdin token

class AbortUsage(Exception):
    pass

class ProcessError(Exception):
    def __init__(self, msg):
        self.msg = msg

PROG = os.path.basename(sys.argv[0]) or "pigz"

def eprint(s: str, opt: Optional[Options]=None):
    if opt is None or not opt.quiet:
        sys.stderr.write(s)

def abort(msg: str):
    sys.stderr.write(f"{PROG}: abort: {msg}\n")
    sys.exit(22)

def parse_num(s: str) -> int:
    try:
        if s == "" or any(c not in "+-0123456789" for c in s):
            raise ValueError
        return int(s, 10)
    except Exception:
        abort(f"invalid numeric parameter: {s}")

def set_level_from_digit(opt: Options, d: str):
    opt.level = int(d)

def apply_option(opt: Options, ch: str, val: Optional[str]=None):
    if ch.isdigit():
        set_level_from_digit(opt, ch); return
    if ch == 'c': opt.stdout = True
    elif ch == 'd': opt.decompress = True
    elif ch == 'f': opt.force = True
    elif ch == 'h': print(HELP_TEXT, end=""); sys.exit(0)
    elif ch == 'H': opt.strategy = zlib.Z_HUFFMAN_ONLY
    elif ch == 'i': opt.independent = True
    elif ch == 'k': opt.keep = True
    elif ch == 'K': opt.zip_mode = True; opt.zlib_mode = False
    elif ch == 'l': opt.list_mode = True; opt.decompress = True
    elif ch == 'L': print(LICENSE_TEXT, end=""); sys.exit(0)
    elif ch == 'm': opt.store_time = False
    elif ch == 'M': opt.store_time = True
    elif ch == 'n': opt.store_name = False; opt.store_time = False
    elif ch == 'N': opt.store_name = True; opt.store_time = True
    elif ch == 'q': opt.quiet = True
    elif ch == 'r': opt.recursive = True
    elif ch == 'R': opt.rsyncable = True
    elif ch == 't': opt.test = True; opt.decompress = True
    elif ch == 'U': opt.strategy = zlib.Z_RLE
    elif ch == 'v': opt.verbose += 1
    elif ch == 'V':
        print(f"pigz {VERSION}")
        if opt.verbose:
            print(f"zlib {ZLIB_VERSION_TEXT}")
        sys.exit(0)
    elif ch == 'Y': opt.sync = True
    elif ch == 'z': opt.zlib_mode = True; opt.zip_mode = False
    elif ch in ('F','O'):
        pass
    elif ch == 'Z':
        abort("invalid option: LZW output not supported: -Z")
    elif ch in ('A','b','C','I','J','p','S'):
        if val is None:
            abort(f"missing parameter after -{ch}")
        if ch == 'A': opt.alias = val
        elif ch == 'b':
            n = parse_num(val)
            if n < 32: abort("block size too small (must be >= 32K)")
            opt.block_k = n
        elif ch == 'C': opt.comment = val
        elif ch == 'p':
            n = parse_num(val)
            if n < 1: abort(f"invalid numeric parameter: {val}")
            opt.processes = n
        elif ch == 'S': opt.suffix = val
        else:
            parse_num(val)  # validate, otherwise unused zopfli knobs
    else:
        abort(f"invalid option: -{ch}")

def parse_args(argv: List[str]) -> Tuple[Options, List[ParsedName]]:
    # gzip compatibility: options can be supplied through environment variables.
    args: List[str] = []
    for env in ("GZIP", "PIGZ"):
        val = os.environ.get(env)
        if val:
            try: args.extend(shlex.split(val))
            except ValueError: args.extend(val.split())
    args.extend(argv[1:])

    opt = Options()
    base = os.path.basename(argv[0])
    if base.startswith("un"):
        opt.decompress = True
        opt.store_name = False
        opt.store_time = False
    names: List[ParsedName] = []
    endopts = False
    i = 0
    long_with_arg = {
        'alias':'A','blocksize':'b','comment':'C','iterations':'I',
        'maxsplits':'J','processes':'p','suffix':'S'
    }
    long_no_arg = {
        'fast': lambda: setattr(opt,'level',1),
        'best': lambda: setattr(opt,'level',9),
        'stdout': lambda: setattr(opt,'stdout',True),
        'to-stdout': lambda: setattr(opt,'stdout',True),
        'decompress': lambda: setattr(opt,'decompress',True),
        'uncompress': lambda: setattr(opt,'decompress',True),
        'force': lambda: setattr(opt,'force',True),
        'help': lambda: (print(HELP_TEXT,end=""), sys.exit(0)),
        'huffman': lambda: setattr(opt,'strategy',zlib.Z_HUFFMAN_ONLY),
        'independent': lambda: setattr(opt,'independent',True),
        'keep': lambda: setattr(opt,'keep',True),
        'zip': lambda: (setattr(opt,'zip_mode',True), setattr(opt,'zlib_mode',False)),
        'list': lambda: (setattr(opt,'list_mode',True), setattr(opt,'decompress',True)),
        'license': lambda: (print(LICENSE_TEXT,end=""), sys.exit(0)),
        'no-time': lambda: setattr(opt,'store_time',False),
        'time': lambda: setattr(opt,'store_time',True),
        'no-name': lambda: (setattr(opt,'store_name',False), setattr(opt,'store_time',False)),
        'name': lambda: (setattr(opt,'store_name',True), setattr(opt,'store_time',True)),
        'quiet': lambda: setattr(opt,'quiet',True),
        'silent': lambda: setattr(opt,'quiet',True),
        'recursive': lambda: setattr(opt,'recursive',True),
        'rsyncable': lambda: setattr(opt,'rsyncable',True),
        'test': lambda: (setattr(opt,'test',True), setattr(opt,'decompress',True)),
        'rle': lambda: setattr(opt,'strategy',zlib.Z_RLE),
        'verbose': lambda: setattr(opt,'verbose',opt.verbose+1),
        'version': lambda: (print(f"pigz {VERSION}"), print(f"zlib {ZLIB_VERSION_TEXT}") if opt.verbose else None, sys.exit(0)),
        'synchronous': lambda: setattr(opt,'sync',True),
        'zlib': lambda: (setattr(opt,'zlib_mode',True), setattr(opt,'zip_mode',False)),
        'first': lambda: None,
        'oneblock': lambda: None,
    }

    while i < len(args):
        a = args[i]
        if endopts:
            names.append(ParsedName(a)); i += 1; continue
        if a == '--':
            endopts = True; i += 1; continue
        if a == '-':
            names.append(ParsedName(None)); i += 1; continue
        if not a.startswith('-') or a == '':
            names.append(ParsedName(a)); i += 1; continue
        if a.startswith('--'):
            item = a[2:]
            if '=' in item:
                key, val = item.split('=',1)
            else:
                key, val = item, None
            if key in long_no_arg and val is None:
                long_no_arg[key](); i += 1; continue
            if key in long_with_arg:
                if val is None:
                    i += 1
                    if i >= len(args): abort(f"missing parameter after --{key}")
                    val = args[i]
                apply_option(opt, long_with_arg[key], val)
                i += 1; continue
            abort(f"invalid option: --{key}")
        # short option cluster
        s = a[1:]
        if s == '11':
            opt.level = 11; i += 1; continue
        j = 0
        while j < len(s):
            ch = s[j]
            if ch == '1' and j + 1 < len(s) and s[j+1] == '1':
                opt.level = 11; j += 2; continue
            if ch in ('A','b','I','J','p','S'):
                if j + 1 < len(s):
                    val = s[j+1:]; j = len(s)
                else:
                    i += 1
                    if i >= len(args): abort(f"missing parameter after -{ch}")
                    val = args[i]
                    j = len(s)
                apply_option(opt, ch, val)
                break
            elif ch == 'C':
                if j + 1 < len(s):
                    abort("invalid usage: -C must be followed by space")
                i += 1
                if i >= len(args): abort("missing parameter after -C")
                apply_option(opt, ch, args[i])
                j = len(s)
                break
            else:
                apply_option(opt, ch)
                j += 1
        i += 1
    if opt.decompress:
        opt.store_name = opt.store_name if any(x in args for x in ['-N','--name']) else opt.store_name
    if opt.zlib_mode:
        opt.suffix = ".zz" if opt.suffix == ".gz" else opt.suffix
    if opt.zip_mode:
        opt.suffix = ".zip" if opt.suffix == ".gz" else opt.suffix
    return opt, names

def strategy_name(opt: Options):
    return opt.strategy

def raw_deflate(data: bytes, opt: Options) -> bytes:
    level = 9 if opt.level == 11 else max(0, min(9, opt.level))
    block = max(1, opt.block_k) * 1024
    if block <= 0 or len(data) <= block:
        co = zlib.compressobj(level, zlib.DEFLATED, -15, 8, opt.strategy)
        return co.compress(data) + co.flush(zlib.Z_FINISH)
    out = bytearray()
    prev = b''
    marker = b'\x00\x00\xff\xff\x00\x00\x00\xff\xff'
    for pos in range(0, len(data), block):
        chunk = data[pos:pos+block]
        last = pos + block >= len(data)
        if (not opt.independent) and prev:
            co = zlib.compressobj(level, zlib.DEFLATED, -15, 8, opt.strategy, zdict=prev)
        else:
            co = zlib.compressobj(level, zlib.DEFLATED, -15, 8, opt.strategy)
        part = co.compress(chunk) + co.flush(zlib.Z_FINISH if last else zlib.Z_SYNC_FLUSH)
        if not last:
            if part.endswith(b'\x00\x00\xff\xff'):
                part = part[:-4]
            if opt.independent:
                part += marker
            else:
                ba = bytearray(part)
                if len(ba) >= 2:
                    ba[-2] |= 0x80
                part = bytes(ba)
        out.extend(part)
        prev = data[max(0, pos + len(chunk) - 32768):pos + len(chunk)]
    return bytes(out)

def gzip_header(opt: Options, in_name: Optional[str], mtime: int) -> bytes:
    flags = 0
    name_bytes = b''
    comm_bytes = b''
    if opt.store_name and in_name:
        name = os.path.basename(in_name)
        if name:
            name_bytes = name.encode('latin-1', 'replace') + b'\x00'
            flags |= 8
    if opt.comment is not None:
        comm_bytes = opt.comment.encode('latin-1', 'replace') + b'\x00'
        flags |= 16
    mt = int(mtime) if opt.store_time else 0
    xfl = 4 if opt.level == 1 else (2 if opt.level in (9,11) else 0)
    return b'\x1f\x8b\x08' + bytes([flags]) + struct.pack('<I', mt & 0xffffffff) + bytes([xfl, 3]) + name_bytes + comm_bytes

def compress_gzip(data: bytes, opt: Options, in_name: Optional[str]=None, mtime: int=0) -> bytes:
    return gzip_header(opt, in_name, mtime) + raw_deflate(data, opt) + struct.pack('<II', zlib.crc32(data) & 0xffffffff, len(data) & 0xffffffff)

def zlib_header_for_level(level: int) -> bytes:
    if level == 1:
        return bytes.fromhex('7801')
    if level in (9,11):
        return bytes.fromhex('78da')
    if level in (6,7,8):
        return bytes.fromhex('785e')
    return bytes.fromhex('789c')

def compress_zlib(data: bytes, opt: Options) -> bytes:
    return zlib_header_for_level(opt.level) + raw_deflate(data, opt) + struct.pack('>I', zlib.adler32(data) & 0xffffffff)

def dos_time_date(ts: int):
    t = time.localtime(ts if ts else time.time())
    dostime = (t.tm_hour << 11) | (t.tm_min << 5) | (t.tm_sec // 2)
    dosdate = ((t.tm_year - 1980) << 9) | (t.tm_mon << 5) | t.tm_mday
    return dostime & 0xffff, dosdate & 0xffff

def compress_zip(data: bytes, opt: Options, in_name: Optional[str]=None, mtime: int=0) -> bytes:
    name = os.path.basename(in_name) if in_name else opt.alias
    if not name: name = '-'
    bio = io.BytesIO()
    # zipfile creates a standard single-entry zip. This differs internally from
    # pigz's streaming zip64 layout in unimportant ways, but is interoperable.
    zi = zipfile.ZipInfo(filename=name)
    ts = mtime if (opt.store_time and mtime) else int(time.time())
    lt = time.localtime(ts)
    zi.date_time = (max(1980, lt.tm_year), lt.tm_mon, lt.tm_mday, lt.tm_hour, lt.tm_min, lt.tm_sec)
    zi.compress_type = zipfile.ZIP_DEFLATED
    zi.comment = (opt.comment or '').encode('latin-1','replace')
    level = 9 if opt.level == 11 else max(0, min(9, opt.level))
    if level == 0:
        zi.compress_type = zipfile.ZIP_STORED
    try:
        with zipfile.ZipFile(bio, 'w', compression=zi.compress_type, compresslevel=level if zi.compress_type == zipfile.ZIP_DEFLATED else None) as zf:
            zf.writestr(zi, data)
    except TypeError:
        with zipfile.ZipFile(bio, 'w', compression=zi.compress_type) as zf:
            zf.writestr(zi, data)
    return bio.getvalue()

@dataclass
class GzipMember:
    data: bytes
    name: Optional[str]
    comment: Optional[str]
    mtime: int
    crc: int
    isize: int
    comp_size: int
    method: str = 'gzip 8'

class GzipFormatError(Exception):
    pass

def _zerr_text(e: zlib.error) -> str:
    msg = str(e)
    if ':' in msg:
        msg = msg.split(':',1)[1].strip()
    return msg

def parse_gzip_members(blob: bytes) -> List[GzipMember]:
    members: List[GzipMember] = []
    pos = 0
    while pos < len(blob):
        if len(blob) - pos == 0: break
        if len(blob) - pos < 10 or blob[pos:pos+2] != b'\x1f\x8b':
            if pos == 0: raise GzipFormatError('unrecognized format')
            # trailing garbage is treated as corruption
            raise GzipFormatError('trailing junk')
        start = pos
        cm = blob[pos+2]; flg = blob[pos+3]
        if cm != 8:
            raise GzipFormatError('unknown compression method')
        mtime = struct.unpack('<I', blob[pos+4:pos+8])[0]
        pos += 10
        if flg & 4:
            if pos + 2 > len(blob): raise GzipFormatError('corrupted -- incomplete header')
            xlen = struct.unpack('<H', blob[pos:pos+2])[0]; pos += 2 + xlen
        name = None; comment = None
        if flg & 8:
            end = blob.find(b'\x00', pos)
            if end < 0: raise GzipFormatError('corrupted -- incomplete header')
            name = blob[pos:end].decode('latin-1', 'replace'); pos = end + 1
        if flg & 16:
            end = blob.find(b'\x00', pos)
            if end < 0: raise GzipFormatError('corrupted -- incomplete header')
            comment = blob[pos:end].decode('latin-1','replace'); pos = end + 1
        if flg & 2:
            pos += 2
        if pos > len(blob): raise GzipFormatError('corrupted -- incomplete header')
        dobj = zlib.decompressobj(-15)
        try:
            data = dobj.decompress(blob[pos:])
            data += dobj.flush()
        except zlib.error as e:
            raise GzipFormatError('corrupted -- invalid deflate data (' + _zerr_text(e) + ')')
        if not dobj.eof:
            raise GzipFormatError('corrupted -- missing trailer')
        trailer_start = len(blob) - len(dobj.unused_data)
        if trailer_start + 8 > len(blob):
            raise GzipFormatError('corrupted -- missing trailer')
        trailer = blob[trailer_start:trailer_start+8]
        crc, isize = struct.unpack('<II', trailer)
        gotcrc = zlib.crc32(data) & 0xffffffff
        if gotcrc != crc:
            raise GzipFormatError('corrupted -- crc32 mismatch')
        if (len(data) & 0xffffffff) != isize:
            raise GzipFormatError('corrupted -- length mismatch')
        comp_size = trailer_start - pos
        members.append(GzipMember(data, name, comment, mtime, crc, isize, comp_size))
        pos = trailer_start + 8
    return members

def decompress_auto(blob: bytes):
    """Return (data, kind, metadata)."""
    if blob.startswith(b'\x1f\x8b'):
        members = parse_gzip_members(blob)
        return b''.join(m.data for m in members), 'gzip', members[0] if members else None
    if blob.startswith(b'PK'):
        try:
            with zipfile.ZipFile(io.BytesIO(blob), 'r') as zf:
                infos = [x for x in zf.infolist() if not x.is_dir()]
                if not infos: raise GzipFormatError('zip has no entries')
                info = infos[0]
                data = zf.read(info)
                meta = {'name': info.filename, 'mtime': int(time.mktime(info.date_time + (0,0,-1))), 'crc': info.CRC, 'comp_size': info.compress_size, 'file_size': info.file_size}
                return data, 'zip', meta
        except GzipFormatError:
            raise
        except Exception as e:
            raise GzipFormatError('corrupted -- invalid zip data')
    # Try zlib wrapper.
    try:
        dobj = zlib.decompressobj(15)
        data = dobj.decompress(blob) + dobj.flush()
        if not dobj.eof and not data:
            raise zlib.error('')
        return data, 'zlib', {'comp_size': max(0, len(blob)-6), 'file_size': 0, 'mtime': 0, 'crc': 0}
    except zlib.error:
        raise GzipFormatError('unrecognized format')

def stripped_name(path: str) -> Optional[str]:
    low = path.lower()
    if low.endswith('.tgz'):
        return path[:-4] + '.tar'
    for suf in ('.gz', '.zz', '.z', '.zip'):
        if low.endswith(suf):
            return path[:-len(suf)]
    # .Z is accepted but lower() covers it as .z
    return None

def display_name_for_list(path: Optional[str], meta_name: Optional[str]) -> str:
    if meta_name:
        return meta_name
    if path:
        s = stripped_name(path)
        return s if s is not None else path
    return "<stdin>"

def ratio_string(comp: int, orig: int) -> str:
    if orig == 0:
        return "-inf%" if comp else "  0.0%"
    val = 100.0 * (1.0 - (comp / float(orig)))
    return f"{val:.1f}%"

def ls_timestamp(ts: int) -> str:
    if not ts:
        return "??? ?? ????"
    now = time.time()
    t = time.localtime(ts)
    if abs(now - ts) > 15552000:  # about six months
        return time.strftime("%b %e  %Y", t)
    else:
        return time.strftime("%b %e %H:%M", t)

def list_one(path: Optional[str], blob: bytes, opt: Options):
    if blob.startswith(b'\x1f\x8b'):
        members = parse_gzip_members(blob)
        if not members: raise GzipFormatError('unrecognized format')
        m = members[0]
        name = display_name_for_list(path, m.name)
        if opt.verbose:
            print(f"{m.method:<7} {m.crc:08x}  {ls_timestamp(m.mtime):>12}  {m.comp_size:10d} {m.isize:10d} {ratio_string(m.comp_size,m.isize):>6}  {name}")
        else:
            print(f"{m.comp_size:10d} {m.isize:10d} {ratio_string(m.comp_size,m.isize):>6}  {name}")
    elif blob.startswith(b'PK'):
        try:
            with zipfile.ZipFile(io.BytesIO(blob),'r') as zf:
                infos=[x for x in zf.infolist() if not x.is_dir()]
                if infos:
                    info=infos[0]; comp=info.compress_size; orig=info.file_size; name=display_name_for_list(path, info.filename)
                else:
                    comp=orig=0; name=display_name_for_list(path,None)
        except Exception:
            comp=orig=0; name=display_name_for_list(path,None)
        if opt.verbose:
            print(f"zip  8  {0:08x}  {'??? ?? ????':>12}  {comp:10d} {orig:10d} {ratio_string(comp,orig):>6}  {name}")
        else:
            print(f"{comp:10d} {orig:10d} {ratio_string(comp,orig):>6}  {name}")
    else:
        # zlib has no stored uncompressed size in the trailer.
        data, kind, meta = decompress_auto(blob)
        comp = max(0, len(blob)-6)
        name = display_name_for_list(path, None)
        if opt.verbose:
            print(f"zlib 8  {zlib.adler32(data)&0xffffffff:08x}  {'??? ?? ????':>12}  {comp:10d} {0:10d} {ratio_string(comp,0):>6}  {name}")
        else:
            print(f"{comp:10d} {0:10d} {ratio_string(comp,0):>6}  {name}")

def write_all_stdout(data: bytes):
    sys.stdout.buffer.write(data)
    try: sys.stdout.buffer.flush()
    except Exception: pass

def skip(path: str, text: str, opt: Options, error: bool=True) -> int:
    eprint(f"{PROG}: skipping: {path} {text}\n", opt)
    return 1 if error else 0

def output_suffix(opt: Options) -> str:
    if opt.zip_mode: return opt.suffix if opt.suffix != '.gz' else '.zip'
    if opt.zlib_mode: return opt.suffix if opt.suffix != '.gz' else '.zz'
    return opt.suffix

def encode_output(data: bytes, opt: Options, name: Optional[str], mtime: int) -> bytes:
    if opt.zip_mode: return compress_zip(data, opt, name, mtime)
    if opt.zlib_mode: return compress_zlib(data, opt)
    return compress_gzip(data, opt, name, mtime)

def process_compress_stdin(opt: Options) -> int:
    data = sys.stdin.buffer.read()
    out = encode_output(data, opt, None, 0)
    write_all_stdout(out)
    return 0

def process_compress_file(path: str, opt: Options) -> int:
    if not os.path.exists(path):
        return skip(path, "does not exist", opt, True)
    try:
        st = os.stat(path)
    except OSError:
        return skip(path, "does not exist", opt, True)
    if stat.S_ISDIR(st.st_mode):
        if not opt.recursive:
            return skip(path, "is a directory", opt, True)
        rc = 0
        for root, dirs, files in os.walk(path):
            for fn in files:
                rc |= process_compress_file(os.path.join(root, fn), opt)
        return rc
    suf = output_suffix(opt)
    if (not opt.force) and path.endswith(suf):
        return skip(path, f"ends with {suf}", opt, False)
    try:
        with open(path,'rb') as f: data = f.read()
    except OSError as e:
        return skip(path, str(e), opt, True)
    out = encode_output(data, opt, path, int(st.st_mtime))
    if opt.stdout:
        if opt.verbose:
            eprint(f"{path} to <stdout> \n", opt)
        write_all_stdout(out)
        return 0
    outpath = path + suf
    if os.path.exists(outpath) and not opt.force:
        return skip(outpath, "exists", opt, True)
    try:
        with open(outpath, 'wb') as f:
            f.write(out)
            if opt.sync:
                f.flush(); os.fsync(f.fileno())
        try: os.utime(outpath, (st.st_atime, st.st_mtime))
        except OSError: pass
        if opt.verbose:
            eprint(f"{path} to {outpath} \n", opt)
        if not opt.keep:
            try: os.remove(path)
            except OSError: pass
        return 0
    except OSError as e:
        return skip(outpath, str(e), opt, True)

def output_name_for_decompress(path: str, kind: str, meta, opt: Options) -> Optional[str]:
    if opt.store_name:
        nm = None
        if kind == 'gzip' and isinstance(meta, GzipMember): nm = meta.name
        elif kind == 'zip' and isinstance(meta, dict): nm = meta.get('name')
        if nm:
            return os.path.join(os.path.dirname(path), os.path.basename(nm))
    return stripped_name(path)

def process_decompress_blob(blob: bytes, path: Optional[str], opt: Options) -> Tuple[int, Optional[bytes], Optional[str], int]:
    try:
        if opt.list_mode:
            if not hasattr(process_decompress_blob, '_header_printed'):
                if opt.verbose:
                    print("method    check    timestamp    compressed   original reduced  name")
                else:
                    print("compressed   original reduced  name")
                setattr(process_decompress_blob, '_header_printed', True)
            list_one(path, blob, opt)
            return 0, None, None, 0
        data, kind, meta = decompress_auto(blob)
        mtime = 0
        if kind == 'gzip' and isinstance(meta, GzipMember): mtime = meta.mtime
        elif kind == 'zip' and isinstance(meta, dict): mtime = meta.get('mtime',0)
        return 0, data, kind, mtime
    except GzipFormatError as e:
        p = path if path is not None else "<stdin>"
        # unrecognized format has no colon in pigz; corruptions do.
        msg = str(e)
        if msg == 'unrecognized format':
            eprint(f"{PROG}: skipping: {p} unrecognized format\n", opt)
        else:
            eprint(f"{PROG}: skipping: {p}: {msg}\n", opt)
        return 1, None, None, 0

def process_decompress_stdin(opt: Options) -> int:
    blob = sys.stdin.buffer.read()
    rc, data, kind, mtime = process_decompress_blob(blob, None, opt)
    if rc or opt.list_mode or opt.test: return rc
    if data is not None: write_all_stdout(data)
    return 0

def process_decompress_file(path: str, opt: Options) -> int:
    if not os.path.exists(path):
        return skip(path, "does not exist", opt, True)
    st = os.stat(path)
    if stat.S_ISDIR(st.st_mode):
        if not opt.recursive: return skip(path, "is a directory", opt, True)
        rc=0
        for root, dirs, files in os.walk(path):
            for fn in files: rc |= process_decompress_file(os.path.join(root, fn), opt)
        return rc
    try:
        blob = open(path,'rb').read()
    except OSError as e:
        return skip(path, str(e), opt, True)
    if opt.stdout:
        rc, data, kind, mtime = process_decompress_blob(blob, path, opt)
        if rc or opt.list_mode or opt.test: return rc
        if data is not None: write_all_stdout(data)
        return 0
    if opt.list_mode or opt.test:
        rc, data, kind, mtime = process_decompress_blob(blob, path, opt)
        return rc
    # For file output, pigz checks for a compressed suffix before inflating.
    if stripped_name(path) is None:
        return skip(path, "does not have compressed suffix", opt, True)
    rc, data, kind, mtime = process_decompress_blob(blob, path, opt)
    if rc: return rc
    # Need metadata for stored name. Reparse light enough.
    try:
        _, k2, meta = decompress_auto(blob)
    except Exception:
        meta = None; k2 = kind
    outpath = output_name_for_decompress(path, k2, meta, opt) or stripped_name(path)
    if outpath is None:
        return skip(path, "does not have compressed suffix", opt, True)
    if os.path.exists(outpath) and not opt.force:
        return skip(outpath, "exists", opt, True)
    try:
        with open(outpath,'wb') as f:
            f.write(data or b'')
            if opt.sync:
                f.flush(); os.fsync(f.fileno())
        # Default without -N uses the compressed file mtime. With -N/-M use header time.
        mt = mtime if (opt.store_time and mtime) else int(st.st_mtime)
        try: os.utime(outpath, (mt, mt))
        except OSError: pass
        if opt.verbose:
            eprint(f"{path} to {outpath} \n", opt)
        if not opt.keep:
            try: os.remove(path)
            except OSError: pass
        return 0
    except OSError as e:
        return skip(outpath, str(e), opt, True)

def expand_recursive_names(names: List[ParsedName], opt: Options) -> List[ParsedName]:
    # Directories are handled in processing to produce the same non-recursive error.
    return names

def main(argv: List[str]) -> int:
    global PROG
    PROG = os.path.basename(argv[0]) or "pigz"
    opt, names = parse_args(argv)
    if opt.decompress:
        # pigz defaults to not restoring header name/time on decompression, unless -N/-M are used.
        # Our parser already honors explicit order; when no env/option touched them after default
        # for normal pigz, set both off. Detect a common explicit -N/-M by scanning original args/env.
        allargs = ' '.join(argv[1:] + shlex.split(os.environ.get('GZIP','') or '') + shlex.split(os.environ.get('PIGZ','') or ''))
        if not any(tok in allargs for tok in ['-N','--name','-M','--time']) and not os.path.basename(argv[0]).startswith('un'):
            opt.store_name = False; opt.store_time = False
    if not names:
        names = [ParsedName(None)]
    rc = 0
    for pn in expand_recursive_names(names,opt):
        if pn.name is None:
            if opt.decompress:
                rc |= process_decompress_stdin(opt)
            else:
                rc |= process_compress_stdin(opt)
        else:
            if opt.decompress:
                rc |= process_decompress_file(pn.name, opt)
            else:
                rc |= process_compress_file(pn.name, opt)
    return 1 if rc else 0

if __name__ == '__main__':
    try:
        sys.exit(main(sys.argv))
    except BrokenPipeError:
        try: sys.stderr.close()
        except Exception: pass
        sys.exit(1)
