s=pathlib.Path('big').read_bytes(); obs=pathlib.Path('o-b_32.gz').read_bytes()[10:-8]
bs=32*1024
outs=[]; prev=b''
for pos in range(0,len(s),bs):
 last=pos+bs>=len(s)
 co=zlib.compressobj(6,zlib.DEFLATED,-15,8,zlib.Z_DEFAULT_STRATEGY,zdict=prev) if prev else zlib.compressobj(6,zlib.DEFLATED,-15,8,zlib.Z_DEFAULT_STRATEGY)
 part=co.compress(s[pos:pos+bs])+co.flush(zlib.Z_FINISH if last else zlib.Z_SYNC_FLUSH)
 outs.append(part); prev=s[max(0,pos+bs-32768):pos+bs]
