# Try each boundary operation strip/tweak or keep.
def build(mask_strip, mask_tweak):
 out=b''
 for i,p in enumerate(outs):
  if i==len(outs)-1: out+=p
  else:
   q=p
   if mask_strip>>i &1 and q.endswith(b'\x00\x00\xff\xff'):
    q=q[:-4]
   if mask_tweak>>i &1:
    ba=bytearray(q)
    # if stripped, -2; if kept, -6 perhaps
    idx=-2 if (mask_strip>>i&1) else -6
    if len(ba)>=abs(idx): ba[idx]|=0x80
    q=bytes(ba)
   out+=q
 return out
n=len(outs)-1
